#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        assert(x>=1 && y>=1 && x+y<=n-1);
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    auto find_pos = [&](int val) -> int {
        for(int i=0;i<n;i++) if(p[i]==val) return i;
        return -1;
    };

    for(int target=0; target<n-1; target++){
        int pos = find_pos(target+1);
        if(pos == target) continue;

        // Move element from pos to position 0 first
        if(pos != 0){
            // x=pos, y=n-1-pos if n-1-pos>=1 and pos>=1 and pos+n-1-pos=n-1<n
            if(pos < n-1){
                apply_op(pos, n-1-pos);
                // element was at pos, now at position (n-1-pos) in new array
                pos = n-1-pos;
            }
            // Now move to front: use y=pos (take last pos elements as suffix), x=1 (if valid)
            // Actually: to bring pos to front, use y=n-pos, x=pos... no.
            // y = n - pos means suffix starts at pos. x can be anything. 
            // We want element at pos to end up at 0. suffix=[pos..n-1] starts with our element.
            // Use y = n-pos, x = pos. But x+y = n > n-1. Use x = pos, y = n-pos-1... no.
            if(pos > 0 && pos <= n-1){
                int y = n - pos;
                int x = pos - 1;
                if(x >= 1 && y >= 1 && x + y <= n-1){
                    apply_op(x, y);
                    pos = 0;
                } else if(pos == n-1){
                    apply_op(1, n-1);
                    pos = 0;
                }
            }
            pos = find_pos(target+1);
        }
        // Now move from position 0 to target
        if(pos == 0 && target > 0){
            // x = target, y = n - target - 1; prefix=[0..target-1], suffix=[target+1..n-1]
            // result: suffix + middle[target..target] + prefix -> element at n-target-1
            // Use y=1, x=target: suffix=[n-1], mid=[target..n-2], prefix=[0..target-1] -> elem at n-1
            // Hmm, use x=1, y=n-1-target if valid: suffix mid prefix, elem(at 0=prefix) goes to end
            if(target <= n-2){
                apply_op(1, n-1-target);
                pos = find_pos(target+1);
                if(pos != target && pos > 0){
                    apply_op(pos, n-1-pos < 1 ? 1 : n-1-pos);
                    pos = find_pos(target+1);
                }
            }
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
